+ * @return 该单位下的系数。
+ */
+static uint64_t mount_humanize(uint64_t bytes, FAR char *label)
+{
+  static const char labels[5] =
+  {
+    'B', 'K', 'M', 'G', 'T'
+  };
+  int which = 0;
+
+  while (which < 4 &&
+         (bytes >= 10240 || ((bytes & 0x3ff) == 0 && bytes != 0)))
