#ifndef CONFIG_FS_PROCFS_EXCLUDE_USAGE
/**
 * @brief 把字节数收成最多 4 位系数加单位（B/K/M/G/T）。
 *
 * 必须用 `uint64_t`：`f_bsize * f_blocks` 在约 14 GiB 窗口上会溢出 32 位
 *（3665920 × 4096 = 15015608320，wrap 成 2032 MiB）。
 *
 * @param bytes 容量字节数。
 * @param[out] label 写入一个单位字符（`B`/`K`/`M`/`G`/`T`）。
 * @return 该单位下的系数。
 */
static uint64_t mount_humanize(uint64_t bytes, FAR char *label)
{
  static const char labels[5] =
  {
    'B', 'K', 'M', 'G', 'T'
  };
  int which = 0;

  while (which < 4 &&
         (bytes >= 10240 || ((bytes & 0x3ff) == 0 && bytes != 0)))
    {
      which++;
      if (bytes >= 10240)
        {
          bytes = (bytes + 512) >> 10;
        }
      else
        {
          bytes >>= 10;
        }
    }

  *label = labels[which];
  return bytes;
}

